def solve(g, mode):
    h,w=len(g),len(g[0])
    off=(lambda r,c:c-r) if mode=='diag' else (lambda r,c:r)
    tracks={}
    for r in range(h):
        for c in range(w):
            if g[r][c]: tracks.setdefault(off(r,c),set()).add(g[r][c])
    # minimal modulus p with consistent color per residue and covering all residues
    for p in range(1,31):
        m={}
        good=True
        for k,vs in tracks.items():
            if len(vs)>1: good=False;break
            v=next(iter(vs)); k%=p
            if m.setdefault(k,v)!=v: good=False;break
        if good and len(m)==p:
            return [[m[(off(r,c))%p] for c in range(w)] for r in range(h)],p
    return None,None
